import numpy as np
from numba import njit


@njit(cache=True)
def _hungarian(cost):
    n = cost.shape[0]
    u = np.zeros(n + 1, dtype=np.float64)
    v = np.zeros(n + 1, dtype=np.float64)
    p = np.zeros(n + 1, dtype=np.int64)
    way = np.zeros(n + 1, dtype=np.int64)
    INF = 1e18
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = np.full(n + 1, INF, dtype=np.float64)
        used = np.zeros(n + 1, dtype=np.bool_)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = -1
            for j in range(1, n + 1):
                if not used[j]:
                    cur = cost[i0 - 1, j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(0, n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    return p


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]

        # For uniform marginals the optimal transport plan is a permutation
        # (a perfect matching), which can be found with the Hungarian algorithm.
        if a.shape[0] == b.shape[0] and np.all(a == a[0]) and np.all(b == b[0]):
            p = _hungarian(M)
            G = np.zeros((n, n), dtype=np.float64)
            for j in range(1, n + 1):
                G[p[j] - 1, j - 1] = a[0]
            return {"transport_plan": G}

        import ot
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}

