#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
#include <time.h>

// auction algorithm for min-cost assignment (maximize -cost)
void auction(int n, const double* cost, int* assign) {
    double* price = (double*)calloc(n, sizeof(double));
    int* a = (int*)malloc(n * sizeof(int));
    int* stack = (int*)malloc(n * sizeof(int));
    for (int j = 0; j < n; j++) a[j] = -1;
    double maxc = 0;
    for (int i = 0; i < n*n; i++) if (cost[i] > maxc) maxc = cost[i];
    double eps = maxc;
    while (eps > 1e-9) {
        for (int j = 0; j < n; j++) a[j] = -1;
        int top = 0;
        for (int i = 0; i < n; i++) stack[top++] = i;
        while (top > 0) {
            int i = stack[--top];
            const double* ci = cost + (size_t)i*n;
            double best = -1e18, second = -1e18;
            int bestj = -1;
            for (int j = 0; j < n; j++) {
                double val = -ci[j] - price[j];
                if (val > best) { second = best; best = val; bestj = j; }
                else if (val > second) second = val;
            }
            double bid = price[bestj] + (best - second) + eps;
            if (a[bestj] != -1) stack[top++] = a[bestj];
            a[bestj] = i;
            price[bestj] = bid;
        }
        eps *= 0.5;
    }
    memcpy(assign, a, n*sizeof(int));
    free(price); free(a); free(stack);
}

// Hungarian O(n^3)
void hungarian(int n, const double* cost, int* assign) {
    double* u = (double*)calloc(n+1, sizeof(double));
    double* v = (double*)calloc(n+1, sizeof(double));
    int* p = (int*)calloc(n+1, sizeof(int));
    int* way = (int*)calloc(n+1, sizeof(int));
    double* minv = (double*)malloc((n+1)*sizeof(double));
    char* used = (char*)malloc((n+1)*sizeof(char));
    const double INF = 1e18;
    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        while (1) {
            used[j0] = 1;
            int i0 = p[j0];
            const double* ci = cost + (size_t)(i0-1)*n;
            double ui = u[i0];
            double delta = INF;
            int j1 = -1;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = ci[j-1] - ui - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
            if (p[j0] == 0) break;
        }
        while (1) {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
            if (j0 == 0) break;
        }
    }
    for (int j = 1; j <= n; j++) assign[j-1] = p[j]-1;
    free(u); free(v); free(p); free(way); free(minv); free(used);
}

int main(int argc, char** argv) {
    int n = 600;
    // generate random cost matrix
    double* cost = (double*)malloc(n*n*sizeof(double));
    srand(1);
    for (int i = 0; i < n*n; i++) cost[i] = (double)rand()/RAND_MAX;
    int* assign = (int*)malloc(n*sizeof(int));
    // warmup
    auction(n, cost, assign);
    hungarian(n, cost, assign);
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 20; r++) auction(n, cost, assign);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ta = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("auction: %.3f ms\n", ta/20*1000);
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < 20; r++) hungarian(n, cost, assign);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double th = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("hungarian: %.3f ms\n", th/20*1000);
    return 0;
}
